mapper.select:
SELECT FROM consult_session c LEFT JOIN shop s ON s.id=c.shop_id LEFT JOIN app_user u ON u.id=c.user_id WHERE c.merchant_id=#{merchantId} AND c.region=#{region} AND c.user_id IS NOT NULL
AND c.shop_id IN #{shopId}
AND 1=0
AND c.merchant_unread > 0
ORDER BY c.updated_at DESC, c.id DESC LIMIT #{limit}

SELECT id,session_id,region,sender_type,sender_id,content,created_at
FROM consult_message WHERE session_id=#{sessionId}
AND id < #{beforeId}
AND id > #{afterId}
ORDER BY id ASCDESC
LIMIT #{limit}

mapper.update:
UPDATE consult_session
SET last_message=#{content},last_message_at=#{now},
    user_unread=user_unread+#{userDelta},merchant_unread=merchant_unread+#{merchantDelta},
    updated_at=#{now}
WHERE id=#{id}
